package com.aluba.travelrecorder;
import android.content.*;
import android.graphics.*;
import android.view.*;
import java.util.*;

final class MapCanvas extends View {
 interface Tap {void at(double lat,double lon,Models.Photo photo,Models.Diary diary);}
 final TravelApplication app;final TileCache tiles;final Paint paint=new Paint(3);final GestureDetector gestures;final ScaleGestureDetector scale;
 List<RouteMath.Point> points=Collections.emptyList();List<Models.Photo> photos=Collections.emptyList();List<Models.Diary> diaries=Collections.emptyList();
 double cx=RouteMath.x(105),cy=RouteMath.y(30);int zoom=4;boolean follow=true,preview=false,showTiles=true;boolean initialized=false;RouteMath.Point replay;Tap tap;Runnable manual=()->{};float scaleSum=1;long replayClock;
 private double cameraX,cameraY;private boolean cameraActive,replayFollowing;private long cameraFrame;
 private final Choreographer.FrameCallback cameraTick=new Choreographer.FrameCallback(){public void doFrame(long now){if(!cameraActive)return;double dt=cameraFrame==0?1.0/60:Math.min(.05,Math.max(0,(now-cameraFrame)/1e9));cameraFrame=now;stepCamera(dt);if(cameraActive)Choreographer.getInstance().postFrameCallback(this);}};
 void targetCamera(double lon,double lat){cameraX=RouteMath.x(lon);cameraY=RouteMath.y(lat);if(!cameraActive){cameraActive=true;cameraFrame=0;Choreographer.getInstance().postFrameCallback(cameraTick);}}
 void stopCamera(){cameraActive=false;cameraFrame=0;Choreographer.getInstance().removeFrameCallback(cameraTick);}
 void stepCamera(double dt){if(!cameraActive)return;double fraction=1-Math.exp(-Math.max(0,dt)/.42);cx+=RouteMath.delta(cameraX-cx)*fraction;cx=cx-Math.floor(cx);cy+=(cameraY-cy)*fraction;invalidate();if(Math.hypot(RouteMath.delta(cameraX-cx),cameraY-cy)*world()<.05)stopCamera();}
 protected void onDetachedFromWindow(){stopCamera();super.onDetachedFromWindow();}
 MapCanvas(Context context,boolean preview){super(context);app=(TravelApplication)context.getApplicationContext();tiles=new TileCache(app);this.preview=preview;showTiles=!preview;setLayerType(View.LAYER_TYPE_SOFTWARE,null);setContentDescription("旅程路线地图");
  gestures=new GestureDetector(context,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(android.view.MotionEvent e){return true;}public boolean onScroll(MotionEvent a,MotionEvent b,float dx,float dy){follow=false;stopCamera();replayFollowing=false;manual.run();cx+=dx/world();cy=Math.max(0,Math.min(1,cy+dy/world()));invalidate();return true;}public boolean onSingleTapUp(MotionEvent e){if(showTiles&&e.getY()>=getHeight()-dp(27)){try{getContext().startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.openstreetmap.org/copyright")));}catch(android.content.ActivityNotFoundException ignored){}return true;}if(tap!=null){double lat=RouteMath.lat(cy+(e.getY()-getHeight()/2.0)/world()),lon=RouteMath.lon(cx+(e.getX()-getWidth()/2.0)/world());Models.Photo photo=null;Models.Diary note=null;for(Models.Photo p:photos)if(p.lat!=null&&Math.abs(sx(p.lon)-e.getX())<dp(26)&&Math.abs(sy(p.lat)-dp(16)-e.getY())<dp(34)){photo=p;break;}if(photo==null)for(Models.Diary d:diaries)if(Math.hypot(sx(d.lon)-e.getX(),sy(d.lat)-e.getY())<dp(20)){note=d;break;}tap.at(lat,lon,photo,note);}return true;}public boolean onDoubleTap(MotionEvent e){zoomBy(1);return true;}});
  scale=new ScaleGestureDetector(context,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScaleBegin(ScaleGestureDetector d){follow=false;stopCamera();replayFollowing=false;manual.run();scaleSum=1;return true;}public boolean onScale(ScaleGestureDetector d){scaleSum*=d.getScaleFactor();if(scaleSum>1.4){zoomBy(1);scaleSum=1;}if(scaleSum<0.7){zoomBy(-1);scaleSum=1;}return true;}});
 }
 float dp(float n){return n*getResources().getDisplayMetrics().density;}
 double world(){return 256.0*(1<<zoom);}
 float sx(double lon){return (float)(getWidth()/2.0+RouteMath.delta(RouteMath.x(lon)-cx)*world());}
 float sy(double lat){return (float)(getHeight()/2.0+(RouteMath.y(lat)-cy)*world());}
 void zoomBy(int dz){follow=false;stopCamera();replayFollowing=false;manual.run();zoom=Math.max(1,Math.min(19,zoom+dz));invalidate();}
 void data(List<RouteMath.Point> route,List<Models.Photo> pictures,List<Models.Diary> notes){points=route;photos=pictures;diaries=notes;if(!initialized&&!route.isEmpty()&&getWidth()>0){if(preview)fit();else{RouteMath.Point p=route.get(route.size()-1);cx=RouteMath.x(p.lon);cy=RouteMath.y(p.lat);zoom=16;}initialized=true;}if(follow&&replay==null&&!route.isEmpty()){RouteMath.Point p=route.get(route.size()-1);targetCamera(p.lon,p.lat);}for(Models.Photo p:pictures)app.photos.load(p.thumb,this::invalidate);invalidate();}
 void recenter(){follow=true;if(!points.isEmpty()){RouteMath.Point p=points.get(points.size()-1);targetCamera(p.lon,p.lat);}invalidate();}
 void fit(){stopCamera();replayFollowing=false;if(points.isEmpty()||getWidth()==0)return;double anchor=RouteMath.x(points.get(0).lon),xmin=anchor,xmax=anchor,ymin=1,ymax=0;for(RouteMath.Point p:points){double x=anchor+RouteMath.delta(RouteMath.x(p.lon)-anchor),y=RouteMath.y(p.lat);xmin=Math.min(xmin,x);xmax=Math.max(xmax,x);ymin=Math.min(ymin,y);ymax=Math.max(ymax,y);}cx=(xmin+xmax)/2;cy=(ymin+ymax)/2;zoom=19;while(zoom>1&&((xmax-xmin)*world()>getWidth()*0.74||(ymax-ymin)*world()>getHeight()*0.72))zoom--;follow=false;invalidate();}
 void replay(RouteMath.Point p,long clock,boolean camera){replay=p;replayClock=clock;if(!camera||p==null){if(replayFollowing)stopCamera();replayFollowing=false;}else{if(!replayFollowing&&(sx(p.lon)<getWidth()*.2||sx(p.lon)>getWidth()*.8||sy(p.lat)<getHeight()*.2||sy(p.lat)>getHeight()*.8))replayFollowing=true;if(replayFollowing)targetCamera(p.lon,p.lat);}invalidate();}

 protected void onSizeChanged(int w,int h,int ow,int oh){if(!points.isEmpty()&&(preview||!initialized)){fit();initialized=true;}}
 protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(preview?Color.WHITE:Color.rgb(240,243,238));paint.setStyle(Paint.Style.FILL);
  if(showTiles){double left=cx*world()-getWidth()/2.0,top=cy*world()-getHeight()/2.0;int x0=(int)Math.floor(left/256),y0=(int)Math.floor(top/256);for(int x=x0;x*256<left+getWidth();x++)for(int y=y0;y*256<top+getHeight();y++){Bitmap b=tiles.tile(zoom,x,y,this::invalidate);if(b!=null)c.drawBitmap(b,null,new RectF((float)(x*256-left),(float)(y*256-top),(float)(x*256-left+256),(float)(y*256-top+256)),paint);}}
  Path path=new Path();RouteMath.Point last=null;for(RouteMath.Point p:points){float x=sx(p.lon),y=sy(p.lat);if(last==null||last.segment!=p.segment)path.moveTo(x,y);else path.lineTo(x,y);last=p;}paint.setColor(Color.rgb(15,123,255));paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(preview?2.8f:3));paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);c.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);
  if(!preview&&!points.isEmpty()){for(int index:new int[]{0,points.size()-1}){RouteMath.Point p=points.get(index);paint.setColor(index==0?Color.rgb(30,173,108):Color.rgb(20,123,255));c.drawCircle(sx(p.lon),sy(p.lat),dp(6),paint);}}
  if(!preview){for(Models.Diary d:diaries){if(!d.photo.isEmpty()&&photos.stream().anyMatch(photo->photo.id.equals(d.photo)&&photo.lat==null))continue;paint.setColor(Color.rgb(255,160,30));c.drawCircle(sx(d.lon),sy(d.lat),dp(7),paint);}for(Models.Photo p:photos)if(p.lat!=null){float x=sx(p.lon),y=sy(p.lat);Bitmap b=app.photos.cached(p.thumb);RectF r=new RectF(x-dp(22),y-dp(50),x+dp(22),y-dp(6));paint.setColor(Color.WHITE);c.drawRoundRect(new RectF(r.left-dp(1.5f),r.top-dp(1.5f),r.right+dp(1.5f),r.bottom+dp(1.5f)),dp(5),dp(5),paint);Path tip=new Path();tip.moveTo(x-dp(5),y-dp(6));tip.lineTo(x,y);tip.lineTo(x+dp(5),y-dp(6));c.drawPath(tip,paint);if(b!=null)drawPhoto(c,b,r,paint);else{paint.setColor(Color.LTGRAY);c.drawRect(r,paint);}}}
  if(replay!=null){float x=sx(replay.lon),y=sy(replay.lat);drawSparks(c,x,y,replayClock,dp(1),paint);}
  if(showTiles){paint.setColor(0xEFFFFFFF);c.drawRect(0,getHeight()-dp(27),getWidth(),getHeight(),paint);paint.setTextSize(dp(10));paint.setColor(Color.DKGRAY);c.drawText("© OpenStreetMap contributors · openstreetmap.org/copyright",dp(5),getHeight()-dp(9),paint);if(tiles.unavailable){paint.setTextSize(dp(12));c.drawText("底图暂不可用 · 轨迹仍会记录",dp(10),dp(20),paint);}}
 }
 static void drawPhoto(Canvas c,Bitmap b,RectF r,Paint p){float scale=Math.max(r.width()/b.getWidth(),r.height()/b.getHeight());float w=r.width()/scale,h=r.height()/scale;Rect src=new Rect((int)((b.getWidth()-w)/2),(int)((b.getHeight()-h)/2),(int)((b.getWidth()+w)/2),(int)((b.getHeight()+h)/2));c.drawBitmap(b,src,r,p);}
 static void drawSparks(Canvas c,float x,float y,long time,float density,Paint p){for(int i=0;i<32;i++){double age=((time+i*83)%1100)/1000.0,angle=i*2.39996,speed=(14+i%9*5)*density;float dx=(float)(Math.cos(angle)*speed*age),dy=(float)(Math.sin(angle)*speed*age+35*density*age*age);int alpha=(int)(255*Math.max(0,1-age/1.1));p.setColor(Color.argb(alpha,255,100+i%5*28,20));p.setStrokeWidth(Math.max(1,2*density*(float)(1-age/1.2)));c.drawLine(x+dx,y+dy,x+dx*(float)(1-0.09/Math.max(.1,age)),y+dy-4*density,p);}p.setColor(0xFFFF302E);c.drawCircle(x,y,5*density,p);p.setColor(0xFFFFECE0);c.drawCircle(x-density,y-density,1.8f*density,p);}
 public boolean onTouchEvent(MotionEvent e){if(preview)return false;if(e.getActionMasked()==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);follow=false;stopCamera();replayFollowing=false;manual.run();}scale.onTouchEvent(e);gestures.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)getParent().requestDisallowInterceptTouchEvent(false);return true;}
}
